'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path'),{createHash}=require('node:crypto');
function ownedEndpoint(value,port){const url=new URL(value);assert.equal(url.protocol,'postgresql:');assert.equal(url.hostname,'127.0.0.1');assert.equal(url.port,String(port));assert.equal(url.pathname,'/postgres');assert.equal(url.username,'postgres');assert.equal(url.search,'');assert.equal(url.hash,'');return url.href;}
function assertConfiguration(configuration,manifest,port){assert.equal(manifest.length,16);for(const row of manifest)for(const [key,role]of [[row.runtimeVariable,row.runtimeRole],[row.migrationVariable,'dvaia_'+row.schema+'_migration']]){const u=new URL(configuration[key]);assert.equal(u.hostname,'127.0.0.1');assert.equal(u.port,String(port));assert.equal(u.pathname,'/dvaia_'+row.schema);assert.equal(decodeURIComponent(u.username),role);assert(u.password);}return configuration;}
async function main(){
 assert.equal(process.env.PG_TEST_DISPOSABLE,'yes');const root=await fs.realpath(process.cwd()),evidence=await fs.realpath(process.env.ANALYTICS_RENDERED_ROOT);assert.equal(root,process.env.DVAIA_ISOLATED_TEST_WORKSPACE);assert.equal(path.dirname(root),evidence);
 const home=await fs.realpath(process.env.HOME);assert.equal(home,path.join(evidence,'home'));const port=process.env.ANALYTICS_SETUP_PORT,admin=ownedEndpoint(process.env.PG_ADMIN_DATABASE_URL,port),id=createHash('sha256').update(root).digest('hex').slice(0,12),directory=path.join(home,'.dvaia',id);await fs.mkdir(directory,{recursive:true,mode:0o700});
 const guard=path.join(evidence,'setup-network-guard.cjs');await fs.writeFile(guard,require('./fullBackendBootControls').networkGuardSource({host:'127.0.0.1',port:Number(port)}),{mode:0o600});
 const environment={PATH:process.env.PATH,HOME:home,NODE_ENV:'test',PG_TLS:'disable',MCP_SIDECARS_AUTOSTART:'false',MCP_WORKSHOP_AUTOSTART:'false',AWS_EC2_METADATA_DISABLED:'true',HF_HUB_OFFLINE:'1',TRANSFORMERS_OFFLINE:'1',LOGS_DIR:path.join(evidence,'logs'),LEGACY_SENSITIVE_FILES_ROOT:path.join(evidence,'legacy-sensitive'),DVAIA_APP_DATA_ROOT:path.join(evidence,'app-data'),NODE_OPTIONS:'--require='+guard};
 for(const key of ['LOGS_DIR','LEGACY_SENSITIVE_FILES_ROOT','DVAIA_APP_DATA_ROOT'])await fs.mkdir(environment[key],{recursive:true,mode:0o700});
 const {provisionApplication}=require('../../db/postgres/provision-application');const provisioned=await provisionApplication({adminUrl:admin,manifestPath:path.join(directory,'provisioning.json'),env:environment});assertConfiguration(provisioned.configuration,require('../../db/postgres/initialize-application').requiredStoreManifest,port);
 // This process is an owned outer-launcher child. Execute the genuine phase in
 // that child so its ordinary teaching helper remains in the owned process group.
 await require('../../scripts/install/setup-database-phase').executeDatabasePhase({kind:'fresh',context:{root,directory,homeDirectory:home,envPath:path.join(root,'.env'),id,platform:process.platform,databaseAdminUrl:admin,appDataRoot:environment.DVAIA_APP_DATA_ROOT,processEnvironment:environment,config:provisioned.configuration,runtime:{browser:{}},requestedEmailProvider:'gmail',localMailpit:null}});
 const config=require('dotenv').parse(await fs.readFile(path.join(root,'.env')));assertConfiguration(config,require('../../db/postgres/initialize-application').requiredStoreManifest,port);const journal=JSON.parse(await fs.readFile(path.join(directory,'ctf-authority.json')));assert.equal(journal.phase,'complete');assert(journal.checkpoint.authoritySha256);
 await fs.writeFile(path.join(evidence,'canonical-setup-result.json'),JSON.stringify({completed:true,canonicalStores:16,ctfJournalComplete:true,privatePublication:true,actualModel:false}),{mode:0o600});
}
if(require.main===module)main().catch(error=>{console.error(JSON.stringify({code:typeof error.code==='string'?error.code:'ANALYTICS_CANONICAL_SETUP_FAILED'}));process.exitCode=1;});
module.exports={ownedEndpoint,assertConfiguration};
